mapper.select:
SELECT a.*, s.name AS store_name
FROM ecom_ad_daily a
JOIN ecom_store s ON s.id = a.store_id

    a.store_id = #{storeId}
    AND a.ad_date >= #{beginDate}
    AND a.ad_date <= #{endDate}

        AND (a.campaign LIKE CONCAT('%', #{keyword}, '%') OR a.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR a.platform_item_id LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY a.ad_date DESC, a.id DESC
